import * as React from "react";
import { ButtonHTMLAttributes } from "react";
import "./IconButton.scss";
import { MpaIcon } from "../icon/MpaIcon";
import {SvgMpaIcon} from "../../assets/icons/index";
import { Tooltip } from "../tooltip";

export interface IconButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * Identifying value for the icon button.
   */
  id: string;
  /**
   * Determines the shape of the icon button: Square, Circle.
   */
  shape?: "square" | "circle";
  /**
   * Determines the styling of the icon button: Primary, Secondary, Tertiary , Success , Error.
   */
  btnType?: "filled" | "outline" | "standard" ;
  /**
   * Determines the colour palette of the icon button.
  */
  colour?: "primary" | "secondary" | "success" | "tertiary" | "error" | "inverse"  | "onSurface";
  /**
   * Determines the size of the button: Small, Medium, Large ,X-Large.
  */
  size?: "small" | "medium" | "large" | "x-large";
  /**
   * React icon object to be displayed icon button .
  */
  icon?: keyof typeof SvgMpaIcon | string;  
  /**
   * Determines if the button can be interacted with.
  */
  disabled?: boolean;
  /**
   * Custom className that can be passed to the element for overriding styling.
  */
  className?: string;
  /**
   * Custom onClick function that can be passed to the element for customizing behavior.
   */
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;

 /**
   * Text to be displayed inside the tooltip.
   */
  tooltipText?: string;
/**
   * The placement of the overlay in relation to the icon.
   */
  tooltipPlacement?: "right" | "left" | "top" | "bottom";
}

const IconButton: React.FC<IconButtonProps> = ({
  id,
  shape = "square",
  btnType = "filled",
  size = "medium",
  className,
  disabled = false,
  icon = "Bell",
  onClick,
  tooltipText,
  tooltipPlacement,
  colour = "primary",
  ...rest
}) => {

  const getIconSize = (size: IconButtonProps["size"]): string => {
    const map: Record<NonNullable<IconButtonProps["size"]>, string> = {
      small: "16",
      medium: "20",
      large: "24",
      "x-large": "32"
    };
    return map[(size || "medium") as NonNullable<IconButtonProps["size"]>];
  };

  const iconSize = getIconSize(size);
  

let buttonClassName = [
  "mpa-icon-btn",
  `mpa-icon-btn-${btnType}`,
  `mpa-icon-btn-${shape}`,  
  `mpa-icon-btn-${size}`,   
  `mpa-icon-btn-${colour}`,
  className,
  disabled ? "disabled" : ""
].filter(Boolean).join(" ");

  return ( 
    <>
      {tooltipText && tooltipText.trim().length > 0 ? (
         <Tooltip className={`mpa-btn-tooltip-text-${tooltipPlacement}`} tooltipText={tooltipText} tooltipPlacement={tooltipPlacement}>
         <button
          id={id}
          className={buttonClassName} 
          aria-disabled={disabled}      
          disabled={disabled}
          onClick={onClick}
          {...rest}
          >
          {icon &&
            <span className={`mpa-icon-style`}> 
                <MpaIcon iconName={icon} size={iconSize}/>
            </span>
          }
         </button>
         </Tooltip>
      ) : (
        <button
            id={id}
            className={buttonClassName} 
            aria-disabled={disabled}      
            disabled={disabled}
            onClick={onClick}
            {...rest}
            >
            {icon &&
            <span className={`mpa-icon-style`}> 
                <MpaIcon iconName={icon} size={iconSize}/>
            </span>
          }      
        </button>
      ) 
      }
    </>
   );
 
};

export default IconButton;
